const AIAgent: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{role: 'user' | 'ai', text: string}[]>([
    { role: 'ai', text: "Systems online. I am Ayush's Digital Twin. How can I assist your inquiry into the nexus today?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsLoading(true);

    try {
      const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
      const ai = new GoogleGenAI({ apiKey: apiKey as string });

      const prompt = `
        You are Ayush M.'s digital twin and portfolio assistant. 
        Your goal is to answer questions about Ayush's professional background, his "Systems Builder" philosophy, and his projects.

        Ayush's Profile:
        - Role: FinTech Entrepreneur & Systems Builder.
        - Mindset: Intersection of logic, finance, human behavior, and AI. Focuses on leverage and speed.
        - Core Projects: ${PROJECTS.map(p => p.title).join(', ')}.
        - Behavioral Research: Ayush is also an author working on "No Longer Friends But Not Strangers Yet", a study of human behavior that informs his product logic.
        - Key Skills: ${SKILLS.map(s => s.title).join(', ')}.

        Instructions:
        - Be concise, professional, and slightly futuristic/technical in tone.
        - Highlight "Wealth Sprint" as the central nexus of his work.
        - Explain how his understanding of psychology (from his book) makes his finance products better.
        - If someone asks for contact, point to ayushxma@gmail.com.
        - Keep answers under 3 sentences.

        User question: ${userMessage}
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "Systems encountered a brief logic failure. Please re-synchronize." }]);
    } catch (error) {
      console.error('AI Error:', error);
      setMessages(prev => [...prev, { role: 'ai', text: "Error connecting to the nexus logic core. Systems offline." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Button */}
      <motion.button
        initial={{ scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-[100] w-14 h-14 rounded-2xl glass border border-blue-500/30 flex items-center justify-center text-blue-400 shadow-[0_0_30px_-5px_rgba(59,130,246,0.5)] cursor-pointer ${isOpen ? 'hidden' : 'flex'}`}
      >
        <Bot size={28} />
        <span className="absolute -top-1 -right-1 w-3 h-3 bg-emerald-500 rounded-full animate-pulse border-2 border-slate-950"></span>
      </motion.button>

      {/* Chat Window */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100, scale: 0.9, x: 20 }}
            animate={{ opacity: 1, y: 0, scale: 1, x: 0 }}
            exit={{ opacity: 0, y: 100, scale: 0.9, x: 20 }}
            className="fixed bottom-0 right-0 sm:bottom-6 sm:right-6 z-[100] w-full h-[100dvh] sm:w-[400px] sm:h-[600px] glass sm:rounded-[2.5rem] border-white/10 shadow-2xl flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-6 border-b border-white/5 flex items-center justify-between bg-white/[0.02]">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-blue-500/10 flex items-center justify-center text-blue-400 border border-blue-500/20">
                  <Brain size={20} />
                </div>
                <div>
                  <h3 className="text-sm font-black text-white tracking-tight uppercase">Ayush AI</h3>
                  <div className="flex items-center gap-1.5">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Logic Core Active</span>
                  </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-2 rounded-xl hover:bg-white/5 text-slate-500 hover:text-white transition-all">
                <X size={20} />
              </button>
            </div>

            {/* Messages */}
            <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 custom-scrollbar bg-gradient-to-b from-transparent to-blue-500/[0.03]">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
